+			return whyLineRange{}, fmt.Errorf("invalid line range %q", raw)
+		}
+		start, err := parseLine(parts[0])
+		if err != nil {
+			return whyLineRange{}, err
+		}
+		end, err := parseLine(parts[1])
+		if err != nil {
+			return whyLineRange{}, err
+		}
+		if start > end {
+			return whyLineRange{}, fmt.Errorf("invalid line range %q: start must be <= end", raw)
+		}
+		return whyLineRange{Start: start, End: end}, nil
+	}
+
+	line, err := parseLine(raw)
+	if err != nil {
+		return whyLineRange{}, err
+	}
